import torch
import torch.nn as nn
import triton
import triton.language as tl


def _to_pair(x):
    return (x, x) if isinstance(x, int) else tuple(x)


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_W": 16, "BLOCK_OC": 32}, num_warps=4, num_stages=3),
    ],
    key=["W_IN", "C_out"],
)
@triton.jit
def _conv_transpose2d_scatter(
    x_ptr,
    w_ptr,
    out_ptr,
    H_IN,
    W_IN,
    C_out,
    OH,
    OW,
    sx_b,
    sx_h,
    sx_w,
    so_b,
    so_h,
    so_w,
    BLOCK_W: tl.constexpr,
    BLOCK_OC: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    C_IN: tl.constexpr,
    STRIDE_H: tl.constexpr,
    STRIDE_W: tl.constexpr,
    DIL_H: tl.constexpr,
    DIL_W: tl.constexpr,
    PAD_H: tl.constexpr,
    PAD_W: tl.constexpr,
):
    pid_w = tl.program_id(0)
    pid_bh = tl.program_id(1)
    pid_oc = tl.program_id(2)

    b = pid_bh // H_IN
    ih = pid_bh % H_IN

    offs_iw = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    offs_oc = pid_oc * BLOCK_OC + tl.arange(0, BLOCK_OC)

    x_base = x_ptr + b.to(tl.int64) * sx_b + ih * sx_h
    x_bp = tl.make_block_ptr(
        base=x_base,
        shape=(W_IN, C_IN),
        strides=(sx_w, 1),
        offsets=(pid_w * BLOCK_W, 0),
        block_shape=(BLOCK_W, C_IN),
        order=(1, 0),
    )
    x_tile = tl.load(x_bp, boundary_check=(0,), padding_option="zero")

    out_batch_base = out_ptr + b.to(tl.int64) * so_b
    iw_valid = offs_iw < W_IN

    for kh in range(KH):
        oh = ih * STRIDE_H + kh * DIL_H - PAD_H
        if (oh >= 0) & (oh < OH):
            for kw in range(KW):
                ow = offs_iw * STRIDE_W + kw * DIL_W - PAD_W

                kidx = kh * KW + kw
                w_bp = tl.make_block_ptr(
                    base=w_ptr + kidx * C_IN * C_out,
                    shape=(C_IN, C_out),
                    strides=(C_out, 1),
                    offsets=(0, pid_oc * BLOCK_OC),
                    block_shape=(C_IN, BLOCK_OC),
                    order=(1, 0),
                )
                w_tile = tl.load(w_bp, boundary_check=(1,), padding_option="zero")

                result = tl.dot(x_tile, w_tile).to(tl.float16)

                out_ptrs = (
                    out_batch_base + oh * so_h + ow[:, None] * so_w + offs_oc[None, :]
                )
                out_mask = (
                    iw_valid[:, None]
                    & (offs_oc[None, :] < C_out)
                    & (ow[:, None] >= 0)
                    & (ow[:, None] < OW)
                )
                tl.store(out_ptrs, result, mask=out_mask)


@triton.jit
def _zero_kernel(out_ptr, N, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    tl.store(out_ptr + offs, tl.zeros((BLOCK,), dtype=tl.float16), mask=mask)


class Model(nn.Module):
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride=1,
        padding=0,
        dilation=1,
        bias=False,
    ):
        super().__init__()
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = _to_pair(kernel_size)
        self.stride_val = _to_pair(stride)
        self.padding_val = _to_pair(padding)
        self.dilation_val = _to_pair(dilation)
        self._packed = False

    def _pack_weights(self):
        w = self.conv_transpose2d.weight.data
        KH, KW = self.kernel_size
        self.weight_packed = (
            w.permute(2, 3, 0, 1)
            .reshape(KH * KW, self.in_channels, self.out_channels)
            .contiguous()
            .to(dtype=torch.float16)
        )
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        device = x.device
        B, C_in, H_in, W_in = x.shape
        KH, KW = self.kernel_size
        SH, SW = self.stride_val
        PH, PW = self.padding_val
        DH, DW = self.dilation_val

        OH = (H_in - 1) * SH - 2 * PH + DH * (KH - 1) + 1
        OW = (W_in - 1) * SW - 2 * PW + DW * (KW - 1) + 1

        x_cl = x.to(dtype=torch.float16).contiguous(memory_format=torch.channels_last)

        if not hasattr(self, "_output") or self._output.shape[0] != B:
            self._output = torch.empty(
                B,
                self.out_channels,
                OH,
                OW,
                device=device,
                dtype=torch.float16,
            ).contiguous(memory_format=torch.channels_last)

        output = self._output
        N_elem = output.numel()
        _zero_kernel[(triton.cdiv(N_elem, 1024),)](output, N_elem, BLOCK=1024)

        sx = x_cl.stride()
        so = output.stride()

        grid = lambda META: (
            triton.cdiv(W_in, META["BLOCK_W"]),
            B * H_in,
            triton.cdiv(self.out_channels, META["BLOCK_OC"]),
        )

        _conv_transpose2d_scatter[grid](
            x_cl,
            self.weight_packed,
            output,
            H_in,
            W_in,
            self.out_channels,
            OH,
            OW,
            sx[0],
            sx[2],
            sx[3],
            so[0],
            so[2],
            so[3],
            KH=KH,
            KW=KW,
            C_IN=C_in,
            STRIDE_H=SH,
            STRIDE_W=SW,
            DIL_H=DH,
            DIL_W=DW,
            PAD_H=PH,
            PAD_W=PW,
        )

        if self.conv_transpose2d.bias is not None:
            output = output + self.conv_transpose2d.bias.view(1, -1, 1, 1)

        return output


batch_size = 16
in_channels = 32
out_channels = 64
kernel_size = 3
height_in = 64
width_in = 128
stride = 5
padding = 1
dilation = 2


def get_inputs():
    x = torch.rand(batch_size, in_channels, height_in, width_in)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size, stride, padding, dilation]
